-- ==========================================
-- Admin UI Seed Data (Manual Offline Insert)
-- Required for all admin.js dashboard panels
-- ==========================================

SET NAMES utf8mb4;
SET time_zone = '+09:00';
START TRANSACTION;

-- ==========================================
-- 1) RMS Mode (m_system_status)
-- ==========================================
ON DUPLICATE KEY UPDATE
  system_name=VALUES(system_name),
  mode=VALUES(mode),
  preparation_ok=VALUES(preparation_ok),
  auto_running=VALUES(auto_running);



-- ==========================================
-- 2) Line States (SQL Query directly in DB)
-- ==========================================

SELECT 
    ML.line_id, 
    ML.line_name, 
    MS.name, 
    MSI.transport_permission,
    MP.pallet_name 
FROM m_station MS
LEFT JOIN m_line ML 
    ON MS.id = ML.line_id 
LEFT JOIN m_system_interlock MSI 
    ON MS.id = MSI.line_id 
LEFT JOIN t_line_station TLS 
    ON MS.id = TLS.pallet_id  -- Corrected this join logic
LEFT JOIN m_location MLO 
    ON MS.cell_type = MLO.cell_type
LEFT JOIN t_location TLO 
    ON TLO.cell_code = MLO.cell_code
LEFT JOIN t_kotatsu_status TKS 
    ON TKS.kotatsu_id = TLO.kotatsu_id  
LEFT JOIN t_pallet_status TPS 
    ON TKS.loaded_pallet_id = TPS.pallet_id 
LEFT JOIN m_pallet MP 
    ON TPS.pallet_type = MP.pallet_type 
ORDER BY ML.line_name, MS.id ASC;

  

-- ==========================================
-- 3) Line Transport Permission (m_system_interlock)
-- ==========================================
ON DUPLICATE KEY UPDATE
  transport_permission=VALUES(transport_permission);

-- ==========================================
-- 4) Task Status (t_task)
-- ==========================================
ON DUPLICATE KEY UPDATE
  destination_cell_code=VALUES(destination_cell_code),
  status=VALUES(status),
  priority=VALUES(priority),
  kotatsu_id=VALUES(kotatsu_id);

-- ==========================================
-- 5) Lift Entrance (t_lift_station)
-- IMPORTANT:
-- Your admin UI requires multiple rows per plat_no,
-- so ensure schema uses PRIMARY KEY (plat_no, seq_no)
-- ==========================================

-- Uncomment this if you need to create seq_no column:
-- ALTER TABLE t_lift_station
--   ADD COLUMN seq_no VARCHAR(16) NOT NULL DEFAULT '間口1',
--   DROP PRIMARY KEY,
--   ADD PRIMARY KEY (plat_no, seq_no);

ON DUPLICATE KEY UPDATE
  pallet_id=VALUES(pallet_id),
  transport_status=VALUES(transport_status),
  updated_date=CURRENT_TIMESTAMP;

ON DUPLICATE KEY UPDATE
  pallet_id=VALUES(pallet_id),
  transport_status=VALUES(transport_status),
  updated_date=CURRENT_TIMESTAMP;

